#include <iostream>
#include <vector>
#include <map>
#include <limits>
#include <cstdio> // For faster input/output
using namespace std;

#define MAX 1000
#define INF (1e9)

struct Edge {
    int to, cost, c;
    Edge(int to, int cost, int c) : to(to), cost(cost), c(c) {}
};

int main() {
    int M, D, N, K;
    int d[MAX][1 << 6];
    while (scanf("%d %d %d %d", &M, &N, &K, &D), M) {
        vector<Edge> G[MAX];
        int cake[MAX]; // Use a static array instead of dynamic vector
        for (int i = 0; i < M; i++) {
            scanf("%d", &cake[i]); // Faster input
        }
        int idx = 0, c;
        string a, b;
        map<string, int> mp;
        for (int i = 0; i < D; i++) {
            cin >> a >> b >> c;
            if (!mp.count(a)) mp[a] = idx++;
            if (!mp.count(b)) mp[b] = idx++;
            if (a[0] == 'C') {
                G[mp[b]].push_back(Edge(mp[a], c, a[1] - '1'));
            } else {
                G[mp[b]].push_back(Edge(mp[a], c, -1));
            }
            if (b[0] == 'C') {
                G[mp[a]].push_back(Edge(mp[b], c, b[1] - '1'));
            } else {
                G[mp[a]].push_back(Edge(mp[b], c, -1));
            }
        }

        int s = mp["H"], t = mp["D"];
        for (int i = 0; i < MAX; i++) {
            fill(d[i], d[i] + (1 << 6), INF);
        }
        d[s][0] = 0;
        bool update = true;

        while (update) {
            update = false;
            for (int i = 0; i < (int)mp.size(); i++) {
                for (int j = 0; j < (int)G[i].size(); j++) {
                    Edge e = G[i][j];
                    for (int S = (1 << 6) - 1; S >= 0; S--) {
                        int ncost = d[i][S];
                        if (ncost == INF) continue;
                        ncost += e.cost * K;
                        if (e.c == -1) {
                            if (ncost < d[e.to][S]) {
                                d[e.to][S] = ncost;
                                update = true;
                            }
                        } else {
                            if (S >> e.c & 1) continue;
                            if (ncost - cake[e.c] < d[e.to][S | (1 << e.c)]) {
                                d[e.to][S | (1 << e.c)] = ncost - cake[e.c];
                                update = true;
                            }
                        }
                    }
                }
            }
        }

        int res = INF;
        for (int i = 0; i < (1 << 6); i++) {
            res = min(res, d[t][i]);
        }

        printf("%d\n", res); // Use printf for faster output
    }
    return 0;
}

