#include <iostream>
#include <vector>
#include <map>
#include <limits>
#include <unordered_map>
#include <queue>
using namespace std;

#define MAX 1000
#define INF (1e9)

struct Edge {
    int to, cost, c;
    Edge(int to, int cost, int c) : to(to), cost(cost), c(c) {}
};

int main() {
    int M, D, N, K;
    while (cin >> M >> N >> K >> D, M) {
        unordered_map<int, vector<Edge>> G;
        vector<int> cake(M);
        for (int i = 0; i < M; i++) {
            cin >> cake[i];
        }

        int idx = 0, c;
        string a, b;
        map<string, int> mp;
        for (int i = 0; i < D; i++) {
            cin >> a >> b >> c;
            if (!mp.count(a)) mp[a] = idx++;
            if (!mp.count(b)) mp[b] = idx++;
            G[mp[b]].emplace_back(mp[a], c, (a[0] == 'C') ? a[1] - '1' : -1);
            G[mp[a]].emplace_back(mp[b], c, (b[0] == 'C') ? b[1] - '1' : -1);
        }

        int s = mp["H"], t = mp["D"];
        vector<vector<int>> d(MAX, vector<int>(1 << 6, INF));
        d[s][0] = 0;

        priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, greater<pair<int, pair<int, int>>>> pq;
        pq.push({0, {s, 0}});

        while (!pq.empty()) {
            auto [cost, state] = pq.top(); pq.pop();
            int node = state.first, S = state.second;
            if (cost > d[node][S]) continue;

            for (auto &edge : G[node]) {
                int ncost = cost + edge.cost * K;
                if (edge.c == -1) {
                    if (ncost < d[edge.to][S]) {
                        d[edge.to][S] = ncost;
                        pq.push({ncost, {edge.to, S}});
                    }
                } else {
                    if (S >> edge.c & 1) continue;
                    if (ncost - cake[edge.c] < d[edge.to][S | (1 << edge.c)]) {
                        d[edge.to][S | (1 << edge.c)] = ncost - cake[edge.c];
                        pq.push({d[edge.to][S | (1 << edge.c)], {edge.to, S | (1 << edge.c)}});
                    }
                }
            }
        }

        int res = INF;
        for (int i = 0; i < (1 << 6); i++) {
            res = min(res, d[t][i]);
        }

        cout << res << endl;
    }
    return 0;
}

